INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21R6ATO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains 9 red tokens, 6 blue tokens, and 10 yellow tokens. If one token is selected at random, what is the probability of selecting a blue token?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{6}{25}$"},{"key":"B","text":"$\\frac{6}{15}$"},{"key":"C","text":"$\\frac{9}{25}$"},{"key":"D","text":"$\\frac{10}{25}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of tokens is $9 + 6 + 10 = 25$. The probability of selecting a blue token is $\\frac{6}{25}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21VZLQS', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A carpenter has at most 58 feet of lumber. Building a shelf requires 4 feet of lumber, and building a bracket requires 3 feet of lumber. If the carpenter builds $s$ shelves and $b$ brackets, which inequality represents this constraint?', NULL, $lyceon_json$[{"key":"A","text":"$4s + 3b \\leq 58$"},{"key":"B","text":"$4s + 3b \\geq 58$"},{"key":"C","text":"$3s + 4b \\leq 58$"},{"key":"D","text":"$4s + 3b < 58$"}]$lyceon_json$::jsonb, 'A', NULL, E'Each shelf uses 4 feet and each bracket uses 3 feet, so the total lumber used is $4s + 3b$. Since the carpenter has at most 58 feet, the total must be less than or equal to 58, giving $4s + 3b \\leq 58$. Reversing the inequality to $\\geq$ would mean the carpenter must use at least 58 feet, which contradicts the constraint. Swapping the coefficients (3 for shelves and 4 for brackets) misassigns the lumber requirements. Using strict inequality ($<$) excludes the case where exactly 58 feet are used, but "at most" includes equality.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM228E764', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $5x + 3 > 38$?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$7$"},{"key":"C","text":"$6$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting 3 from both sides gives $5x > 35$. Dividing both sides by 5 gives $x > 7$. Among the choices, only $8$ is greater than 7.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22M3D2H', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'If $-5 < 2 - 3t \\leq 11$, what is the range of values for $t$?', NULL, $lyceon_json$[{"key":"A","text":"$-3 \\leq t < \\frac{7}{3}$"},{"key":"B","text":"$-3 < t \\leq \\frac{7}{3}$"},{"key":"C","text":"$-3 \\leq t < \\frac{13}{3}$"},{"key":"D","text":"$-3 < t < \\frac{7}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtract 2 from all three parts: $-7 < -3t \\leq 9$. Dividing by $-3$ reverses both inequality signs: $\\frac{7}{3} > t \\geq -3$, which is equivalent to $-3 \\leq t < \\frac{7}{3}$. The choice $-3 < t \\leq \\frac{7}{3}$ results from failing to reverse the inequality directions when dividing by a negative number. The choice with $\\frac{13}{3}$ arises from incorrectly adding 2 instead of subtracting in the first step, producing $-3 < -3t \\leq 13$ and then $-\\frac{13}{3} \\leq t < 1$, with the upper bound miscomputed. The choice $-3 < t < \\frac{7}{3}$ incorrectly treats both inequalities as strict, losing the equality at $t = -3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22WJKQM', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A food truck sells burritos for 11 dollars each and empanadas for 3 dollars each. On a particular day, the truck sold a total of 47 items and collected 293 dollars in revenue. How many burritos were sold?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$19$"},{"key":"C","text":"$23$"},{"key":"D","text":"$28$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $b$ represent burritos and $e$ represent empanadas. The system is $b + e = 47$ and $11b + 3e = 293$. From the first equation, $e = 47 - b$. Substituting into the revenue equation: $11b + 3(47 - b) = 293$, so $11b + 141 - 3b = 293$, giving $8b = 152$ and $b = 19$. Then $e = 47 - 19 = 28$. Verification: $11(19) + 3(28) = 209 + 84 = 293$. The value 28 is the number of empanadas, not burritos, which results from misidentifying which quantity the question asks for. The value 23 comes from an arithmetic error during simplification. The value 14 results from setting up the revenue equation with swapped prices.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM231MZ16', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'If the system of equations $y = 3x + 2$ and $y = x^2 + 5x - 7$ has solutions $(x_1, y_1)$ and $(x_2, y_2)$, what is the value of $x_1 + x_2$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$-2$"},{"key":"C","text":"$9$"},{"key":"D","text":"$-9$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the equations equal: $3x + 2 = x^2 + 5x - 7$. Rearranging: $0 = x^2 + 2x - 9$. By Vieta''s formulas, the sum of the roots is $-\\frac{b}{a} = -\\frac{2}{1} = -2$. The value $2$ results from dropping the negative sign in Vieta''s formula. The value $9$ comes from misreading the constant term as the sum. The value $-9$ comes from a sign error when rearranging the equation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2325NOV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 employees found that 68 commute by car, 47 commute by train, and 31 commute by both car and train. If an employee who commutes by car is selected at random, what is the probability that this employee also commutes by train?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{31}{200}$"},{"key":"B","text":"$\\frac{31}{68}$"},{"key":"C","text":"$\\frac{31}{47}$"},{"key":"D","text":"$\\frac{84}{200}$"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question: given that the employee commutes by car, find the probability they also commute by train. The number who commute by car is 68, and of those, 31 also commute by train, so the conditional probability is $\\frac{31}{68}$. Using $\\frac{31}{200}$ treats it as an unconditional probability over all employees. Using $\\frac{31}{47}$ incorrectly conditions on train commuters instead of car commuters. Using $\\frac{84}{200}$ adds car and train users without subtracting the overlap, then divides by the total.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM233IFQV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A class of 19 students has a mean test score of 74. When a twentieth student joins and takes the same test, the class mean increases to 75. What score did the twentieth student receive?', NULL, $lyceon_json$[{"key":"A","text":"79"},{"key":"B","text":"94"},{"key":"C","text":"80"},{"key":"D","text":"95"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the original 19 scores is 19 times 74 = 1,406. The new mean of 20 students is 75, so the new total is 20 times 75 = 1,500. The twentieth student scored 1,500 minus 1,406 = 94. The value 79 comes from incorrectly assuming the new student scored 5 more than the old mean. The value 80 results from adding the mean increase of 1 to the old mean of 74 and then adding 5. The value 95 comes from an arithmetic slip when computing 20 times 75 or 19 times 74.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23PC7YF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company tested a new sleep aid by recruiting volunteers from three hospitals. Volunteers chose whether to take the sleep aid or a placebo for 8 weeks. At the end of the trial, the sleep aid group reported sleeping an average of 43 minutes longer per night than the placebo group. A company press release stated that the sleep aid was proven to increase nightly sleep duration. Which of the following is the most significant flaw in the company''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The study lasted only 8 weeks, which is too short to draw conclusions."},{"key":"B","text":"Volunteers chose their own group, so differences in sleep duration could be due to preexisting differences between groups rather than the treatment."},{"key":"C","text":"The sample was too small to detect a meaningful difference."},{"key":"D","text":"The study did not measure total sleep duration with a medical device."}]$lyceon_json$::jsonb, 'B', NULL, E'The most significant flaw is that volunteers self-selected into the treatment or placebo group rather than being randomly assigned. Without random assignment, the groups may differ systematically in ways that affect sleep duration (for example, those who chose the sleep aid may have been more motivated to improve their sleep habits), making it impossible to attribute the difference to the sleep aid alone. While 8 weeks may seem short, the duration is not the primary methodological concern. The problem does not indicate the sample was too small, and the stem does not identify measurement method as the central issue.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24WSPBN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'The ages, in years, of 7 employees at a company are 23, 29, 31, 34, 37, 41, and 52. If the employee aged 52 is replaced by a new employee aged 38, what is the new mean age, rounded to the nearest tenth?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '33.3', ARRAY['33.3'], E'The original sum of ages is 23 + 29 + 31 + 34 + 37 + 41 + 52 = 247. Replacing 52 with 38 gives a new sum of 247 minus 52 plus 38 = 233. The new mean is 233 divided by 7, which equals approximately 33.3. A common error is dividing by 6 instead of 7, or forgetting to subtract 52 before adding 38.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24ZC3QB', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What is the value of $x$ if $\\frac{5x - 3}{2} + 4 = 3x - 1$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Multiply both sides by $2$: $(5x - 3) + 8 = 6x - 2$. Combine like terms on the left: $5x + 5 = 6x - 2$. Subtract $5x$ from both sides: $5 = x - 2$. Add $2$ to both sides: $x = 7$. Verification: $\\frac{5(7) - 3}{2} + 4 = \\frac{32}{2} + 4 = 16 + 4 = 20$, and $3(7) - 1 = 20$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM254RCD9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In right triangle $PQR$, angle $Q$ is a right angle and $\\sin(P) = \\frac{24}{25}$. What is the value of $\\tan(R)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7/24', ARRAY['7/24', '0.291', '.291', '0.292', '.292'], E'Since $P + R = 90°$ in a right triangle, $\\sin(P) = \\cos(R) = \\frac{24}{25}$. Using the Pythagorean identity, $\\sin(R) = \\sqrt{1 - \\cos^2(R)} = \\sqrt{1 - \\frac{576}{625}} = \\sqrt{\\frac{49}{625}} = \\frac{7}{25}$. Therefore, $\\tan(R) = \\frac{\\sin(R)}{\\cos(R)} = \\frac{7/25}{24/25} = \\frac{7}{24}$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25G5QJW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 10x + 4y - 7 = 0$. What is the radius of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$36$"},{"key":"C","text":"$\\sqrt{7}$"},{"key":"D","text":"$\\sqrt{22}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Complete the square: $(x^2 - 10x + 25) + (y^2 + 4y + 4) = 7 + 25 + 4$, which gives $(x - 5)^2 + (y + 2)^2 = 36$. The radius is $\\sqrt{36} = 6$. The value $36$ is $r^2$, failing to take the square root to find $r$. The value $\\sqrt{7}$ treats the constant term $7$ as $r^2$ without completing the square. The value $\\sqrt{22}$ results from an arithmetic error when summing the completing-the-square constants.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25I8ZUR', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(-2, 11)$ and $(6, -13)$. What is the $x$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5/3', ARRAY['5/3', '1.666', '1.667'], E'The slope is $\\frac{-13 - 11}{6 - (-2)} = \\frac{-24}{8} = -3$. Using point-slope form with $(-2, 11)$: $y - 11 = -3(x + 2)$, which simplifies to $y = -3x + 5$. Setting $y = 0$ to find the $x$-intercept: $0 = -3x + 5$, so $x = \\frac{5}{3}$.', NULL, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26Z5DAQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'grid_in', E'A researcher collects data on the number of practice sessions (\\(x\\)) and the typing speed in words per minute (\\(y\\)) for a group of participants. The line of best fit is \\(y = 1.9x + 26\\). One participant had 14 practice sessions and a measured typing speed of 57 words per minute. What is the residual for this participant?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4.4', ARRAY['22/5', '4.4'], E'The predicted typing speed for 14 sessions is y = 1.9(14) + 26 = 26.6 + 26 = 52.6 words per minute. The residual is the actual value minus the predicted value: 57 minus 52.6 equals 4.4. A common error is computing the residual as predicted minus actual, yielding -4.4. Another error is substituting incorrectly into the equation.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM275T4TH', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'A membership gym charges a monthly fee plus a per-visit charge. Last month, member A visited $11$ times and was charged a total of 94 dollars. Member B visited $17$ times and was charged a total of 136 dollars. If member C was charged a total of 122 dollars last month, how many times did member C visit?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15', ARRAY['15'], E'Let $b$ be the monthly fee and $r$ be the per-visit charge. From member A: $11r + b = 94$. From member B: $17r + b = 136$. Subtracting: $6r = 42$, so $r = 7$. Substituting back: $b = 94 - 11(7) = 94 - 77 = 17$. For member C: $17 + 7v = 122$, so $7v = 105$ and $v = 15$. Member C visited $15$ times.', NULL, NULL, 'draft', 1, 95, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AW2XVW', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $4x - 9y = 27$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -3)$"},{"key":"B","text":"$(0, 3)$"},{"key":"C","text":"$(0, 27)$"},{"key":"D","text":"$(0, -27)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting $x = 0$ gives $-9y = 27$, so $y = -3$. The $y$-intercept is $(0, -3)$. The point $(0, 3)$ reflects a sign error when dividing $27$ by $-9$. The point $(0, 27)$ reflects a concept gap, treating the constant term as the $y$-intercept without substituting and solving. The point $(0, -27)$ reflects an equation setup error, such as multiplying $27$ by $-1$ without dividing by $9$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BWL87P', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A circle has a radius of $9$ units. A central angle of the circle subtends an arc whose length is $\\frac{21\\pi}{2}$ units. What is the measure, in degrees, of this central angle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '210', ARRAY['210'], E'The arc length formula is $s = r\\theta$, where $\\theta$ is in radians. Substituting: $\\frac{21\\pi}{2} = 9\\theta$, so $\\theta = \\frac{21\\pi}{18} = \\frac{7\\pi}{6}$ radians. Converting to degrees: $\\frac{7\\pi}{6} \\times \\frac{180^\\circ}{\\pi} = \\frac{7 \\times 180}{6} = \\frac{1260}{6} = 210^\\circ$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CQM6Z9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $ABC$, point $D$ lies on side $\\overline{BC}$ such that $\\overline{AD}$ bisects $\\angle BAC$. If $AB = 14$, $AC = 21$, and $BC = 25$, what is the length of $BD$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'By the angle bisector theorem, $\\frac{BD}{DC} = \\frac{AB}{AC} = \\frac{14}{21} = \\frac{2}{3}$. Since $BD + DC = BC = 25$, let $BD = 2k$ and $DC = 3k$. Then $2k + 3k = 25$, so $5k = 25$ and $k = 5$. Therefore $BD = 2(5) = 10$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DPKV4F', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A factory produces 91 bolts every 7 minutes. At this constant rate, how many bolts does the factory produce in 45 minutes?', NULL, $lyceon_json$[{"key":"A","text":"495"},{"key":"B","text":"585"},{"key":"C","text":"637"},{"key":"D","text":"455"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is 91 bolts per 7 minutes, which simplifies to 13 bolts per minute. Multiplying 13 by 45 gives 585 bolts. The value 495 results from an arithmetic slip when multiplying 13 by 45 incorrectly. The value 637 comes from incorrectly setting up the calculation as 91 multiplied by 7. The value 455 results from only multiplying the original 91 by 5, ignoring the unit rate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E4JGOM', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = 2(0.85)^x$. Which of the following statements correctly describes the end behavior of $f$?', NULL, $lyceon_json$[{"key":"A","text":"As $x \\to \\infty$, $f(x) \\to \\infty$, and as $x \\to -\\infty$, $f(x) \\to 0$"},{"key":"B","text":"As $x \\to \\infty$, $f(x) \\to 0$, and as $x \\to -\\infty$, $f(x) \\to -\\infty$"},{"key":"C","text":"As $x \\to \\infty$, $f(x) \\to 0$, and as $x \\to -\\infty$, $f(x) \\to \\infty$"},{"key":"D","text":"As $x \\to \\infty$, $f(x) \\to 2$, and as $x \\to -\\infty$, $f(x) \\to 0$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $0 < 0.85 < 1$, the function $f(x) = 2(0.85)^x$ is an exponential decay function. As $x \\to \\infty$, $(0.85)^x \\to 0$, so $f(x) \\to 0$. As $x \\to -\\infty$, $(0.85)^x = \\frac{1}{(0.85)^{|x|}} \\to \\infty$, so $f(x) \\to \\infty$. The statement that $f(x) \\to \\infty$ as $x \\to \\infty$ incorrectly treats this as exponential growth. The statement that $f(x) \\to -\\infty$ as $x \\to -\\infty$ is wrong because exponential functions with a positive coefficient never take negative values. The claim that $f(x) \\to 2$ as $x \\to \\infty$ confuses the initial value with a horizontal asymptote in the positive direction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
