INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FDRBZF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'Two polls each surveyed residents of the same town about support for a proposed park. Poll X surveyed 150 residents and found $54\\%$ support with a margin of error of $\\pm 7\\%$. Poll Y surveyed 900 residents and found $49\\%$ support with a margin of error of $\\pm 3\\%$. Which of the following statements is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"Poll Y's result is more reliable because its larger sample size produces a smaller margin of error."},{"key":"B","text":"Poll X's result is more reliable because it shows higher support."},{"key":"C","text":"The two polls contradict each other, so neither result can be trusted."},{"key":"D","text":"The true level of support is exactly $49\\%$ because Poll Y surveyed more people."}]$lyceon_json$::jsonb, 'A', NULL, E'A larger random sample produces a smaller margin of error, giving a more precise estimate of the population proportion. Poll Y''s sample of 900 yields a $\\pm 3\\%$ margin compared to Poll X''s $\\pm 7\\%$ from 150 respondents, making Poll Y''s estimate more reliable. Higher support in Poll X does not make its result more reliable; reliability depends on precision, not the magnitude of the estimate. The polls'' confidence intervals actually overlap ($47\\%$--$61\\%$ for Poll X and $46\\%$--$52\\%$ for Poll Y), so they do not necessarily contradict each other. Claiming the true value is exactly $49\\%$ ignores that even the larger poll has a margin of error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GFA4TC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. One of the alternate interior angles measures $53^\\circ$. What is the measure of the other alternate interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$53^\\circ$"},{"key":"B","text":"$127^\\circ$"},{"key":"C","text":"$37^\\circ$"},{"key":"D","text":"$106^\\circ$"}]$lyceon_json$::jsonb, 'A', NULL, E'Alternate interior angles formed by two parallel lines cut by a transversal are congruent, so the other angle also measures $53^\\circ$. The value $127^\\circ$ comes from computing the supplement ($180^\\circ - 53^\\circ$), confusing alternate interior angles with co-interior (same-side interior) angles. The value $37^\\circ$ comes from subtracting from $90^\\circ$ instead of recognizing the congruence. The value $106^\\circ$ comes from doubling the given angle, which has no geometric basis here.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IAQY6N', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangle has a length of $13$ inches and a width of $9$ inches. What is the area, in square inches, of the rectangle?', NULL, $lyceon_json$[{"key":"A","text":"$117$"},{"key":"B","text":"$44$"},{"key":"C","text":"$22$"},{"key":"D","text":"$130$"}]$lyceon_json$::jsonb, 'A', NULL, E'The area of a rectangle is length times width: $13 \\times 9 = 117$ square inches. The value $44$ is the perimeter ($2 \\times 13 + 2 \\times 9 = 44$), confusing area with perimeter. The value $22$ is half the perimeter ($13 + 9 = 22$), computing only the sum of two sides. The value $130$ results from an arithmetic slip, such as computing $13 \\times 10$ instead of $13 \\times 9$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IK2T3P', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 250 residents in a city found that $62\\%$ support a new recycling program. The margin of error for the survey is $4\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between $58\\%$ and $66\\%$ of all residents in the city are likely to support the recycling program."},{"key":"B","text":"Exactly $62\\%$ of all residents in the city support the recycling program."},{"key":"C","text":"Between $58\\%$ and $66\\%$ of the 250 surveyed residents support the recycling program."},{"key":"D","text":"The survey is inaccurate because the margin of error is not zero."}]$lyceon_json$::jsonb, 'A', NULL, E'A margin of error of $4\\%$ around a sample proportion of $62\\%$ means the plausible range for the true population proportion is $62\\% \\pm 4\\%$, or $58\\%$ to $66\\%$. Stating exactly $62\\%$ ignores sampling variability entirely. Applying the interval to the sample itself rather than the population misunderstands the purpose of the margin of error, which estimates the population parameter. Claiming the survey is inaccurate because the margin of error is nonzero reflects a misunderstanding, since all sample-based estimates have some margin of error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IOWGKE', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $6x - 9 = 21$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$\\frac{7}{2}$"},{"key":"C","text":"$5$"},{"key":"D","text":"$30$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding $9$ to both sides gives $6x = 30$, and dividing both sides by $6$ gives $x = 5$. The value $-5$ results from a sign error when dividing $30$ by $6$. The value $\\frac{7}{2}$ results from dividing $21$ by $6$ without first adding $9$, an equation setup error. The value $30$ results from stopping after isolating $6x$ without completing the division, reflecting partial reasoning.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J1FVRS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a scatterplot is given by \\(y = 2.3x + 11\\). According to this model, what is the predicted value of \\(y\\) when \\(x = 9\\)?', NULL, $lyceon_json$[{"key":"A","text":"31.7"},{"key":"B","text":"29.3"},{"key":"C","text":"20.7"},{"key":"D","text":"119.7"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting x = 9 into the equation gives y = 2.3(9) + 11 = 20.7 + 11 = 31.7. The value 29.3 results from an arithmetic slip in computing 2.3 times 9. The value 20.7 comes from computing only the 2.3(9) term and omitting the constant 11. The value 119.7 results from multiplying 2.3 by 9 and then by 11 instead of adding 11.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JE1VGW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the exterior angle at vertex $R$ measures $139^\\circ$. If $\\angle P = 7x + 4$ and $\\angle Q = 5x - 1$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{136}{12}$"},{"key":"B","text":"$\\frac{41}{12}$"},{"key":"C","text":"$\\frac{136}{2}$"},{"key":"D","text":"$\\frac{139}{12}$"}]$lyceon_json$::jsonb, 'A', NULL, E'By the exterior angle theorem, the exterior angle at $R$ equals the sum of the two non-adjacent interior angles: $\\angle P + \\angle Q = 139^\\circ$. So $(7x + 4) + (5x - 1) = 139$, which gives $12x + 3 = 139$, then $12x = 136$, and $x = \\frac{136}{12}$. The value $\\frac{41}{12}$ results from incorrectly setting only one angle equal to the exterior angle and solving a different equation. The value $\\frac{136}{2}$ results from dividing by $2$ instead of $12$, misidentifying the coefficient of $x$. The value $\\frac{139}{12}$ results from forgetting to subtract $3$ before dividing, misreading the simplified equation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K6B5KE', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg measures $9$ and the hypotenuse measures $\\sqrt{130}$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$8$"},{"key":"C","text":"$\\sqrt{211}$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the Pythagorean theorem: $a^2 + 9^2 = 130$, so $a^2 = 130 - 81 = 49$, giving $a = 7$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KRV87Q', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'A town''s population increased from 8,300 to 9,213 over one year. What is the percent increase? (Round to the nearest whole number.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'The increase is 9,213 minus 8,300, which equals 913. The percent increase is 913 divided by 8,300, which equals approximately 0.11, or 11 percent. A common error is dividing by 9,213 instead of 8,300, giving approximately 9.9 percent. Another error is computing the difference incorrectly.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KRXBJQ', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $5x - 3y = 21$. Line $q$ is perpendicular to line $p$ and passes through the point $(7, -2)$. What is the equation of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$3x + 5y = 11$"},{"key":"B","text":"$5x - 3y = 41$"},{"key":"C","text":"$3x - 5y = 31$"},{"key":"D","text":"$5x + 3y = 29$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting line $p$ in slope-intercept form: $y = \\frac{5}{3}x - 7$, so its slope is $\\frac{5}{3}$. A perpendicular line has slope $-\\frac{3}{5}$. Using point-slope form with $(7, -2)$: $y + 2 = -\\frac{3}{5}(x - 7)$. Multiplying through by $5$: $5y + 10 = -3x + 21$, which gives $3x + 5y = 11$. The equation $5x - 3y = 41$ has slope $\\frac{5}{3}$, which is parallel to line $p$ rather than perpendicular, reflecting a concept gap about perpendicular slopes. The equation $3x - 5y = 31$ has slope $\\frac{3}{5}$, using the reciprocal without negating it, a sign error. The equation $5x + 3y = 29$ has slope $-\\frac{5}{3}$, which negates the original slope rather than taking the negative reciprocal, an equation setup error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L0K22Z', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'After a 15 percent discount, the price of a bicycle is 493 dollars. A 7 percent sales tax is then applied to the discounted price. What is the total amount paid, in dollars, rounded to the nearest cent?', NULL, $lyceon_json$[{"key":"A","text":"527.51"},{"key":"B","text":"540.64"},{"key":"C","text":"493.00"},{"key":"D","text":"580.00"}]$lyceon_json$::jsonb, 'A', NULL, E'The discounted price is 493 dollars. The sales tax is 7 percent of 493, which is 0.07 times 493 equals 34.51. The total amount is 493 plus 34.51 equals 527.51 dollars. The value 540.64 results from first computing the original price as 580 dollars and then applying 7 percent tax to that original price instead of the discounted price. The value 493.00 omits the sales tax entirely, paying only the discounted price. The value 580.00 is the original price before the 15 percent discount (493 divided by 0.85) and ignores the tax calculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L2O9DW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A recipe calls for 3 cups of rice to make a dish that serves 11 people. If the same recipe is scaled to serve 77 people, how many cups of rice are needed?', NULL, $lyceon_json$[{"key":"A","text":"18"},{"key":"B","text":"21"},{"key":"C","text":"33"},{"key":"D","text":"24"}]$lyceon_json$::jsonb, 'B', NULL, E'The scaling factor is 77 divided by 11, which equals 7. Multiplying 3 cups by 7 gives 21 cups. The value 18 results from an arithmetic error in the multiplication step. The value 33 comes from incorrectly multiplying 3 by 11 instead of by the scaling factor. The value 24 results from rounding or miscalculating the scaling factor as 8.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LQ7Q86', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g(x) = 4 \\cdot 3^x$ models the population of a bacterial colony after $x$ hours. What does the value $4$ represent in this function?', NULL, $lyceon_json$[{"key":"A","text":"The population triples every hour"},{"key":"B","text":"The initial population of the colony"},{"key":"C","text":"The population after $3$ hours"},{"key":"D","text":"The rate of growth per hour"}]$lyceon_json$::jsonb, 'B', NULL, E'In an exponential function of the form $a \\cdot b^x$, the coefficient $a$ represents the initial value when $x = 0$, since $g(0) = 4 \\cdot 3^0 = 4 \\cdot 1 = 4$. So $4$ is the initial population of the colony. The statement that the population triples every hour describes the base $3$, not the coefficient. The population after $3$ hours confuses the role of the base with the time input. The rate of growth per hour conflates the coefficient with the growth factor.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MTOX08', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{5x^2 + 17x - 12}{x + 4} = ax + b$, where $a$ and $b$ are constants, what is the value of $a - b$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$8$"},{"key":"C","text":"$-8$"},{"key":"D","text":"$-2$"}]$lyceon_json$::jsonb, 'B', NULL, E'Performing polynomial long division of $5x^2 + 17x - 12$ by $x + 4$: the first term is $5x$ (since $5x(x + 4) = 5x^2 + 20x$). Subtracting gives $17x - 20x = -3x$; bringing down $-12$ yields $-3x - 12$. Then $-3(x + 4) = -3x - 12$ with remainder $0$. So $a = 5$ and $b = -3$, giving $a - b = 5 - (-3) = 8$. The value $2$ results from computing $a + b = 5 + (-3)$ instead of $a - b$. The value $-8$ reverses the sign of the correct answer. The value $-2$ results from computing $b - a$ instead of $a - b$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N8Z8IO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health magazine reported that people who drink green tea daily have lower blood pressure than those who do not. The report was based on a survey in which participants self-reported their tea-drinking habits and had their blood pressure measured. What type of study is this?', NULL, $lyceon_json$[{"key":"A","text":"A controlled experiment"},{"key":"B","text":"An observational study"},{"key":"C","text":"A sample survey with a margin of error"},{"key":"D","text":"A randomized clinical trial"}]$lyceon_json$::jsonb, 'B', NULL, E'Because the researchers did not assign participants to drink or avoid green tea but instead observed their existing habits, this is an observational study. A controlled experiment or randomized clinical trial would require researchers to randomly assign participants to treatment and control groups. While the study involves surveying participants, calling it merely a sample survey with a margin of error mischaracterizes it, since the study''s purpose is to compare outcomes between groups defined by their existing behavior, not simply to estimate a single population parameter.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NTCO03', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'A ramp rises at an angle of $23^\\circ$ from the horizontal. If the ramp covers a horizontal distance of $17$ feet, which expression gives the vertical rise of the ramp, in feet?', NULL, $lyceon_json$[{"key":"A","text":"$17 \\tan(23^\\circ)$"},{"key":"B","text":"$17 \\sin(23^\\circ)$"},{"key":"C","text":"$17 \\cos(23^\\circ)$"},{"key":"D","text":"$\\frac{17}{\\tan(23^\\circ)}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The vertical rise is the side opposite the $23^\\circ$ angle, and the horizontal distance is the side adjacent to it. Since $\\tan(\\theta) = \\frac{\\text{opposite}}{\\text{adjacent}}$, the vertical rise equals $17 \\tan(23^\\circ)$. Using $17 \\sin(23^\\circ)$ incorrectly treats $17$ as the hypotenuse rather than the adjacent side. Using $17 \\cos(23^\\circ)$ confuses the roles of sine and cosine relative to the given angle. Dividing $17$ by $\\tan(23^\\circ)$ inverts the tangent relationship, which would give the adjacent side if $17$ were the opposite side.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O1E9Q7', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h$ is defined by $h(x) = -(x - 7)^2 + 13$. What is the maximum value of $h(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$13$"},{"key":"C","text":"$-13$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'B', NULL, E'The function $h(x) = -(x - 7)^2 + 13$ is a downward-opening parabola in vertex form $a(x - h)^2 + k$ with vertex at $(7, 13)$. Since $a = -1 < 0$, the parabola opens downward and the vertex gives the maximum value, which is $13$. The value $7$ is the $x$-coordinate of the vertex, not the maximum output. The value $-13$ results from incorrectly applying the negative sign to the constant. The value $-7$ confuses the negation with the horizontal shift.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ONQOIL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains the values 3, 7, 13, 17, 22, and 28. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"13"},{"key":"B","text":"15"},{"key":"C","text":"17"},{"key":"D","text":"14"}]$lyceon_json$::jsonb, 'B', NULL, E'The six values in order are 3, 7, 13, 17, 22, 28. For an even number of data points, the median is the average of the two middle values. The third and fourth values are 13 and 17, so the median is (13 + 17) divided by 2, which equals 15. The value 13 results from choosing only the lower of the two middle values. The value 17 results from choosing only the upper of the two middle values. The value 14 comes from an arithmetic error when averaging 13 and 17.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OZK77K', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers at a university randomly assigned 120 students to two groups. One group studied with background music for 3 weeks, while the other group studied in silence. At the end of the study, the group that studied with background music scored an average of 6 points higher on a memory test. Which of the following conclusions is best supported by the study design?', NULL, $lyceon_json$[{"key":"A","text":"Background music causes improved memory test scores in university students."},{"key":"B","text":"Background music causes improved memory test scores in all people."},{"key":"C","text":"There is an association between background music and memory test scores, but causation cannot be established."},{"key":"D","text":"Students who prefer music are naturally better at memory tasks."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the researchers used random assignment to place students into treatment and control groups, the study is a randomized experiment, which can support a causal conclusion within the studied population. Concluding that background music causes improved scores in university students is appropriate. Extending the causal claim to all people overgeneralizes beyond the population studied. Stating that only an association can be established ignores that random assignment specifically allows causal inference. Claiming students who prefer music are naturally better introduces a confounding explanation that the random assignment was designed to eliminate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PM04D1', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'For what value of $a$ does the equation $a(x + 3) - 7x = -2x + 19$ have no solution?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{3}$"},{"key":"B","text":"$5$"},{"key":"C","text":"$9$"},{"key":"D","text":"$-2$"}]$lyceon_json$::jsonb, 'B', NULL, E'Expanding the left side: $ax + 3a - 7x = (a - 7)x + 3a$. The right side is $-2x + 19$. For no solution, the coefficients of $x$ must be equal while the constant terms differ: $a - 7 = -2$, giving $a = 5$. Checking constants: $3(5) = 15 \\neq 19$, confirming no solution. The value $\\frac{19}{3}$ comes from setting only the constants equal ($3a = 19$) without matching the $x$-coefficients, which is partial reasoning. The value $9$ comes from solving $a - 7 = 2$ instead of $a - 7 = -2$, a sign error. The value $-2$ comes from reading the coefficient on the right side directly without solving, a misread of the question.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PQKGW1', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many distinct real solutions does the equation $2x^2 - 13x + 21 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'C', NULL, E'The discriminant is $b^2 - 4ac = (-13)^2 - 4(2)(21) = 169 - 168 = 1$. Since the discriminant is positive, there are $2$ distinct real solutions. Answering $0$ reflects incorrectly computing a negative discriminant. Answering $1$ results from an arithmetic slip such as computing $169 - 169 = 0$. Answering $3$ reflects a misconception that a quadratic can have three real solutions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PWXW3D', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $18$ units. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$18\\pi$"},{"key":"B","text":"$9\\pi$"},{"key":"C","text":"$81\\pi$"},{"key":"D","text":"$36\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The circumference of a circle is $C = \\pi d = 18\\pi$. The value $9\\pi$ results from using the radius ($9$) instead of the diameter in the formula $C = \\pi d$, or equivalently computing $\\pi r$ instead of $2\\pi r$. The value $81\\pi$ results from computing $\\pi r^2 = \\pi(9)^2$, which is the area rather than the circumference. The value $36\\pi$ results from using $2\\pi d$ instead of $\\pi d$, doubling the correct circumference.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QTZKIW', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $4(3x - 2) + 7x$?', NULL, $lyceon_json$[{"key":"A","text":"$19x - 8$"},{"key":"B","text":"$19x - 2$"},{"key":"C","text":"$12x - 8$"},{"key":"D","text":"$19x + 8$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $12x - 8 + 7x = 19x - 8$. The expression simplifies to $19x - 8$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RICQZM', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = -4x + 23$. What is the value of $g(-3)$?', NULL, $lyceon_json$[{"key":"A","text":"$-35$"},{"key":"B","text":"$-11$"},{"key":"C","text":"$11$"},{"key":"D","text":"$35$"}]$lyceon_json$::jsonb, 'D', NULL, E'Substituting $x = -3$: $g(-3) = -4(-3) + 23 = 12 + 23 = 35$. The value $11$ results from evaluating $-4(3) + 23 = -12 + 23$, treating the input as positive $3$ instead of $-3$, a sign error. The value $-11$ results from computing $-4(-3) - 23 = 12 - 23$, subtracting the constant instead of adding it, an arithmetic slip. The value $-35$ results from computing $-4(3) - 23 = -12 - 23$, combining both errors.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TBFFGZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A scatterplot shows the relationship between hours of sunlight per day (\\(x\\)) and the number of flowers blooming in a garden (\\(y\\)). The line of best fit is \\(y = 4.7x - 18.6\\). What does the slope of the line represent in this context?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of sunlight, the predicted number of flowers increases by 4.7"},{"key":"B","text":"For each additional flower, the predicted hours of sunlight increases by 4.7"},{"key":"C","text":"When there are zero hours of sunlight, the predicted number of flowers is 4.7"},{"key":"D","text":"The total number of flowers in the garden is 4.7 times the number of hours of sunlight"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of a linear model represents the predicted change in the dependent variable (y, flowers) for each one-unit increase in the independent variable (x, hours of sunlight). The slope is 4.7, so each additional hour of sunlight predicts 4.7 more flowers. The interpretation that reverses the variables confuses the independent and dependent variables. The interpretation involving zero hours of sunlight describes the y-intercept, not the slope. The interpretation about the total number being 4.7 times the hours ignores the y-intercept and treats the relationship as purely multiplicative.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TNKK8B', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A car travels 238 miles using 8.5 gallons of fuel. The fuel tank holds 13 gallons. If the car begins a 410-mile trip with a full tank at this constant fuel efficiency, how many additional gallons of fuel will the car need to purchase during the trip? (Round to the nearest tenth.)', NULL, $lyceon_json$[{"key":"A","text":"1.6"},{"key":"B","text":"2.1"},{"key":"C","text":"1.8"},{"key":"D","text":"14.6"}]$lyceon_json$::jsonb, 'A', NULL, E'The fuel efficiency is 238 divided by 8.5, which equals 28 miles per gallon. The total fuel needed for 410 miles is 410 divided by 28, approximately 14.643 gallons. Since the tank holds 13 gallons, the additional fuel needed is 14.643 minus 13, approximately 1.6 gallons. The value 2.1 comes from an arithmetic slip in the division. The value 1.8 results from rounding intermediate values prematurely. The value 14.6 comes from reporting the total fuel needed rather than the additional fuel beyond the full tank.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TOORWT', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cone has a base radius of $6$ cm and a height of $11$ cm. What is the volume, in cubic centimeters, of the cone?', NULL, $lyceon_json$[{"key":"A","text":"$132\\pi$"},{"key":"B","text":"$396\\pi$"},{"key":"C","text":"$66\\pi$"},{"key":"D","text":"$264\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(6)^2(11) = \\frac{1}{3}\\pi(396) = 132\\pi$ cubic centimeters. The value $396\\pi$ results from computing $\\pi r^2 h$ without the $\\frac{1}{3}$ factor, using the cylinder formula instead. The value $66\\pi$ results from using $\\frac{1}{3}\\pi r h$ without squaring the radius. The value $264\\pi$ results from using $\\frac{2}{3}\\pi r^2 h$, confusing the cone formula with the hemisphere formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V8CCOK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A jar contains 9 tokens numbered 1 through 9. Two tokens are drawn at random without replacement. What is the probability that both tokens show odd numbers?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{18}$"},{"key":"B","text":"$\\frac{25}{81}$"},{"key":"C","text":"$\\frac{1}{6}$"},{"key":"D","text":"$\\frac{5}{9}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The odd numbers from 1 through 9 are 1, 3, 5, 7, and 9, giving 5 odd tokens out of 9 total. The probability the first token is odd is $\\frac{5}{9}$. Without replacement, the probability the second token is also odd is $\\frac{4}{8} = \\frac{1}{2}$. Multiplying gives $\\frac{5}{9} \\times \\frac{1}{2} = \\frac{5}{18}$. The value $\\frac{25}{81}$ results from using $\\frac{5}{9} \\times \\frac{5}{9}$, incorrectly treating the draws as with replacement. The value $\\frac{1}{6}$ comes from an arithmetic error in the multiplication. The value $\\frac{5}{9}$ represents the probability for only the first draw, stopping before completing the second step.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VKYPJV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A shirt originally priced at 47 dollars is on sale for 30 percent off. What is the sale price, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"14.10"},{"key":"B","text":"32.90"},{"key":"C","text":"17.00"},{"key":"D","text":"61.10"}]$lyceon_json$::jsonb, 'B', NULL, E'The discount is 30 percent of 47, which is 0.30 times 47 equals 14.10. The sale price is 47 minus 14.10, which equals 32.90 dollars. The value 14.10 is the discount amount, not the sale price. The value 17.00 results from an arithmetic error in computing the discount. The value 61.10 comes from adding the discount to the original price instead of subtracting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VZDK1I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A researcher surveys a random sample of 400 households in a county and finds that $37\\%$ have installed solar panels. The margin of error is $\\pm 4.8\\%$. A second researcher surveys a random sample of 1,600 households from the same county and finds that $41\\%$ have installed solar panels. If the margin of error is inversely proportional to the square root of the sample size, which of the following is closest to the margin of error for the second survey?', NULL, $lyceon_json$[{"key":"A","text":"$\\pm 1.2\\%$"},{"key":"B","text":"$\\pm 2.4\\%$"},{"key":"C","text":"$\\pm 3.2\\%$"},{"key":"D","text":"$\\pm 4.8\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'When the margin of error is inversely proportional to $\\sqrt{n}$, quadrupling the sample size from 400 to 1,600 multiplies $\\sqrt{n}$ by $\\sqrt{4} = 2$, which halves the margin of error. So $\\frac{4.8\\%}{2} = 2.4\\%$. The value $\\pm 1.2\\%$ results from dividing by 4 (the ratio of sample sizes) instead of by $\\sqrt{4}$. The value $\\pm 3.2\\%$ comes from an incorrect proportionality calculation. The value $\\pm 4.8\\%$ assumes the margin of error stays the same regardless of sample size.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WGLKYW', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A plumber charges a fixed service fee plus a constant rate per hour of work. For a job lasting $4$ hours, the total charge is 218 dollars. For a job lasting $7$ hours, the total charge is 329 dollars. What is the plumber''s fixed service fee, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$37$"},{"key":"B","text":"$47$"},{"key":"C","text":"$70$"},{"key":"D","text":"$148$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let the fixed fee be $b$ and the hourly rate be $m$. Then $4m + b = 218$ and $7m + b = 329$. Subtracting the first equation from the second: $3m = 111$, so $m = 37$. Substituting back: $b = 218 - 4(37) = 218 - 148 = 70$. The fixed service fee is 70 dollars. The value $37$ is the hourly rate, not the fixed fee, reflecting partial reasoning that stops at the rate. The value $47$ comes from dividing the total charge of 329 dollars by 7 hours, ignoring the fixed fee entirely, an equation setup error. The value $148$ is $4 \\times 37$, the variable portion of the 4-hour charge, resulting from an arithmetic slip of reporting the product rather than subtracting it from the total.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
