INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X0P6UT', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution of $x^2 + 5x - 36 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Factoring gives $(x + 9)(x - 4) = 0$, so $x = -9$ or $x = 4$. The positive solution is $4$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XMW56W', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{9x^4 - 25}{3x^2 + 5}$?', NULL, $lyceon_json$[{"key":"A","text":"$3x^2 + 5$"},{"key":"B","text":"$3x^2 - 5$"},{"key":"C","text":"$9x^2 - 5$"},{"key":"D","text":"$3x^2 - \\frac{5}{3}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $9x^4 - 25$ is a difference of squares: $(3x^2)^2 - 5^2 = (3x^2 + 5)(3x^2 - 5)$. Dividing by $3x^2 + 5$ cancels one factor, leaving $3x^2 - 5$. The expression $3x^2 + 5$ incorrectly keeps the positive sign from the divisor factor. The expression $9x^2 - 5$ fails to take the square root of the $9x^4$ term properly. The expression $3x^2 - \\frac{5}{3}$ incorrectly divides the constant $5$ by $3$ instead of recognizing the factored cancellation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZHXQZD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A rectangular prism has dimensions $7$ cm, $9$ cm, and $4$ cm. A second rectangular prism has a square base with side length $6$ cm. If both prisms have the same volume, what is the height, in centimeters, of the second prism?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'The volume of the first prism is $7 \\times 9 \\times 4 = 252$ cubic centimeters. The second prism has a square base with side length $6$, so its base area is $6^2 = 36$ square centimeters. Setting the volumes equal: $36h = 252$, so $h = \\frac{252}{36} = 7$ centimeters.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20DL1Z2', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Historians have long attributed the decline of the Ancestral Puebloan settlement at Chaco Canyon primarily to a prolonged drought in the late 1200s. Recent strontium isotope analysis of timber used in the canyon''s great houses, however, shows that construction wood was imported from mountain ranges over 75 kilometers away, suggesting the community had already developed extensive supply networks to compensate for local resource scarcity. _______ the drought may have been less a sudden catastrophe than the final strain on a system that had been adapting to environmental limits for decades.', E'Historians have long attributed the decline of the Ancestral Puebloan settlement at Chaco Canyon primarily to a prolonged drought in the late 1200s. Recent strontium isotope analysis of timber used in the canyon''s great houses, however, shows that construction wood was imported from mountain ranges over 75 kilometers away, suggesting the community had already developed extensive supply networks to compensate for local resource scarcity. _______ the drought may have been less a sudden catastrophe than the final strain on a system that had been adapting to environmental limits for decades.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"In other words,"},{"key":"C","text":"Granted,"},{"key":"D","text":"Nonetheless,"}]$lyceon_json$::jsonb, 'B', NULL, E'The final sentence restates the implication of the isotope evidence in more interpretive terms: the drought was not a sudden catastrophe but the last pressure on an already-strained system. "In other words," correctly signals that the third sentence is rephrasing the conclusion suggested by the evidence in the second sentence. "Furthermore," would introduce an additional, distinct point, but the final sentence does not add new information; it reframes what was already implied. "Granted," concedes a point before introducing a counterargument, but the final sentence reinforces rather than opposes the preceding evidence. "Nonetheless," signals that a conclusion holds despite a complication, but there is no complication being overcome; the final sentence aligns with the preceding analysis.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
