INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22B2846', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'The fruit fly Drosophila melanogaster has been a staple of genetics laboratories for over a century. Its genome was fully sequenced in the year 2000, revealing approximately 13,600 genes. <u>Many of these genes have counterparts in the human genome that are associated with diseases such as Parkinson''s and diabetes.</u> This genetic overlap has made the fruit fly an indispensable model for studying human health conditions.', $lyceon_json$[{"key":"A","text":"It provides a specific detail that supports the claim made in the following sentence."},{"key":"B","text":"It introduces a new line of inquiry that the rest of the text goes on to explore."},{"key":"C","text":"It qualifies an earlier assertion about the fruit fly's role in laboratories."},{"key":"D","text":"It summarizes the text's central argument about genome sequencing."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the underlined sentence provides a specific detail supporting the claim in the following sentence. The underlined sentence identifies that many fruit fly genes have human disease-associated counterparts, and the next sentence concludes that this genetic overlap makes fruit flies indispensable for studying human health -- a claim directly supported by the detail about shared genes. The choice about introducing a new line of inquiry is wrong because the text does not go on to explore a new topic; it draws a conclusion. The choice about qualifying an earlier assertion misidentifies the rhetorical function, since the underlined sentence adds evidence rather than limiting or restricting a previous claim. The choice about summarizing the central argument is wrong because the underlined sentence presents one specific fact, not a summary of the whole passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22S12OI', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The painted bunting, a songbird found in the southeastern United States, exhibits striking sexual dimorphism: males display vivid blue, green, and red plumage, while females are uniformly olive-green. Ornithologists have long attributed the males'' bright coloring to sexual selection, noting that females prefer more colorful mates. However, a recent study found that male painted buntings with the most saturated plumage also had the fewest ectoparasites. This correlation suggests that bright plumage may serve not only as an aesthetic signal to potential mates but also as ________', $lyceon_json$[{"key":"A","text":"an indication of the male's overall physiological health and parasite resistance."},{"key":"B","text":"a warning to predators that the male is toxic or unpalatable."},{"key":"C","text":"evidence that female painted buntings select mates based on territory size rather than appearance."},{"key":"D","text":"a mechanism for regulating the male's body temperature in warm climates."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that brighter males have fewer parasites, so bright plumage logically serves as an indicator of health and parasite resistance, completing the idea that it functions as more than just an aesthetic signal. The suggestion about warning predators of toxicity introduces aposematism, which is unconnected to the passage''s discussion of mate selection and parasite loads. The claim about territory-based selection contradicts the passage, which states that females prefer more colorful mates. The idea about body temperature regulation has no basis in the passage''s discussion of plumage color and parasites.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW243S8LF', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the first?', E'The blanket octopus (Tremoctopus violaceus) displays one of the most extreme examples of sexual dimorphism in the animal kingdom. Females can grow to nearly two meters in length and possess flowing membranes between their dorsal arms that they unfurl when threatened, creating an imposing silhouette. Males, by contrast, rarely exceed three centimeters and weigh roughly forty thousand times less than females.
