INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26SDO6E', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the central claim of the text?', E'Historian Mariana Velasco has challenged the conventional periodization of the Mesoamerican Postclassic era (roughly 900-1521 CE), which divides it into Early and Late subperiods based primarily on the rise and fall of the Toltec polity. Velasco argues that this division imposes a Central Mexican framework on a region encompassing dozens of distinct political and cultural traditions. Pointing to ceramic sequences from the Mixteca Alta, obsidian exchange networks in western Guatemala, and maritime trade routes along the Yucatan coast, she demonstrates that significant political and economic transformations in these areas occurred on timelines that do not align with the Toltec-centered narrative. Velasco proposes instead a polycentric model that identifies at least five overlapping chronological frameworks, each anchored to the documented trajectories of different regional centers.', $lyceon_json$[{"key":"A","text":"The standard division of the Mesoamerican Postclassic era is too centered on Toltec history and should be replaced by a polycentric model reflecting diverse regional timelines."},{"key":"B","text":"The Mixteca Alta, western Guatemala, and the Yucatan coast developed independently of Central Mexican influence throughout the Postclassic era."},{"key":"C","text":"Ceramic and obsidian evidence proves that the Toltec polity had less political influence than historians previously assumed."},{"key":"D","text":"Periodization in Mesoamerican archaeology is inherently arbitrary and should be abandoned in favor of continuous chronological analysis."}]$lyceon_json$::jsonb, 'A', NULL, E'Velasco''s central claim, as stated in the passage, is that the conventional Toltec-centered periodization imposes a single framework on a diverse region, and she proposes a polycentric alternative with multiple regional chronologies. The correct choice captures both the critique and the proposed replacement. The claim that the Mixteca Alta, western Guatemala, and the Yucatan coast developed independently of Central Mexican influence goes further than the passage, which says their timelines do not align with the Toltec narrative but does not assert complete independence. The claim about Toltec political influence seizes on only one aspect of the evidence while missing Velasco''s broader argument about periodization models. The claim that periodization should be abandoned entirely overstates Velasco''s position; she proposes a different periodization model, not the elimination of periodization.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW281ZPWQ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Geochemist Lena Borovik has analyzed strontium isotope ratios in tooth enamel from 143 individuals buried at the Bronze Age site of Kamenka in southern Siberia (circa 1800-1500 BCE). The local geological baseline for strontium isotopes at Kamenka is well established, allowing Borovik to distinguish individuals who grew up near the site from those who migrated there during childhood. Surprisingly, forty-one percent of the individuals show non-local isotope signatures, and these non-local individuals are distributed evenly across all burial types, including the richest graves containing gold ornaments and bronze weapons. Borovik argues that this pattern undermines the prevailing assumption that Kamenka''s elite were drawn exclusively from local lineages, and instead suggests that ________', $lyceon_json$[{"key":"A","text":"social status at Kamenka was accessible to migrants and was not determined solely by local birth, since individuals of non-local origin attained the same elite burial treatment as locally born individuals."},{"key":"B","text":"the strontium isotope method is unreliable for determining migration patterns because geological baselines can shift over centuries due to erosion and sediment transport."},{"key":"C","text":"the forty-one percent of non-local individuals were likely captured in raids and held as laborers, which would explain their presence at the site without implying social mobility."},{"key":"D","text":"Kamenka was primarily a trading outpost rather than a permanent settlement, and most individuals buried there were transient merchants passing through the region."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that non-local individuals appear in all burial types, including the richest graves, and that this undermines the assumption of exclusively local elites. The logical conclusion is that social status was accessible to migrants, not restricted to local lineages. The claim that the strontium isotope method is unreliable contradicts the passage''s statement that the local baseline is well established, and it would undermine rather than extend Borovik''s own argument. The suggestion that non-local individuals were captured laborers contradicts the key evidence that they are found in elite graves with gold and bronze, which would not characterize captive laborers. The claim that Kamenka was primarily a trading outpost introduces an interpretation unsupported by the passage, which describes it as a burial site with established geological baselines and rich graves, not as a transient trading post.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B9HFRX', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'While many seventeenth-century Dutch painters depicted domestic interiors with lavish attention to material surfaces -- the sheen of pewter, the translucence of glassware -- Pieter de Hooch''s later courtyard scenes exhibit a more ______ quality, subordinating fine detail to the interplay of architectural geometry and raking afternoon light.', $lyceon_json$[{"key":"A","text":"austere"},{"key":"B","text":"garish"},{"key":"C","text":"derivative"},{"key":"D","text":"nostalgic"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "austere." The passage contrasts other Dutch painters'' lavish attention to material detail with de Hooch''s later work, which subordinates fine detail in favor of geometry and light. "Austere" -- meaning severe, stripped-down, or unadorned -- precisely captures this shift away from ornate surface rendering. "Garish" means tastelessly showy or bright, which is the opposite of the restrained quality described. "Derivative" means imitative of another''s work, but the passage presents de Hooch''s approach as a distinctive departure, not an imitation. "Nostalgic" means characterized by longing for the past, which describes an emotional tone the passage never attributes to these courtyard scenes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BMF7FW', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the controlled burns conducted along the perimeter of the wetland nor the manual removal of invasive phragmites from the interior marshland ______ as effective as the introduction of native seedlings, which gradually outcompeted the invasive species for sunlight and soil nutrients.', $lyceon_json$[{"key":"A","text":"have been"},{"key":"B","text":"are"},{"key":"C","text":"were"},{"key":"D","text":"was"}]$lyceon_json$::jsonb, 'D', NULL, E'In a "neither...nor" construction, the verb agrees in number with the nearer subject. The subject closer to the verb is "the manual removal," which is singular, requiring the singular verb "was." The plural past-tense "were" incorrectly treats the compound subject as plural; although the first element ("the controlled burns") is plural, standard agreement rules for "neither...nor" require matching the nearer subject. The present-tense forms "have been" and "are" conflict with the past-tense context established by "outcompeted" later in the sentence. Only the singular past-tense "was" satisfies both the agreement rule and the temporal context.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CHZQKM', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Marine biologist Sylvia Earle has argued that establishing large-scale marine protected areas is the most effective strategy for preserving ocean biodiversity. Critics counter that such reserves displace commercial fishing fleets, concentrating fishing pressure on unprotected waters and potentially worsening overall stock depletion. _______ some recent studies from the Coral Triangle suggest that fish populations in waters adjacent to well-enforced reserves actually increase over time, as reproductive spillover from the protected zone replenishes surrounding areas.', E'Marine biologist Sylvia Earle has argued that establishing large-scale marine protected areas is the most effective strategy for preserving ocean biodiversity. Critics counter that such reserves displace commercial fishing fleets, concentrating fishing pressure on unprotected waters and potentially worsening overall stock depletion. _______ some recent studies from the Coral Triangle suggest that fish populations in waters adjacent to well-enforced reserves actually increase over time, as reproductive spillover from the protected zone replenishes surrounding areas.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"For example,"},{"key":"C","text":"That said,"},{"key":"D","text":"Accordingly,"}]$lyceon_json$::jsonb, 'C', NULL, E'The second sentence presents a criticism that reserves worsen fishing pressure on unprotected waters. The third sentence introduces research showing that adjacent fish populations actually increase thanks to spillover, which counters the critics'' concern. "That said," correctly acknowledges the preceding criticism while pivoting to evidence that undermines it. "Moreover," would add a point that supports the critics'' argument, but the third sentence contradicts rather than extends the criticism. "For example," would illustrate the critics'' claim with a specific case, but the Coral Triangle data refutes rather than exemplifies the displacement concern. "Accordingly," implies the third sentence follows logically from the criticism, but the research finding contradicts the expected consequence of displacement.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CPQGLY', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1903, physicist Philipp Lenard demonstrated that the energy of electrons ejected from a metal surface depends on the frequency of the incoming light, not its intensity. This finding contradicted the prevailing wave theory, which predicted that brighter light should produce more energetic electrons regardless of frequency. Two years later, Albert Einstein proposed that light consists of discrete packets of energy -- photons -- whose individual energy is proportional to their frequency. Einstein''s explanation accounted for Lenard''s puzzling results and ultimately helped establish quantum mechanics as a new framework in physics.', $lyceon_json$[{"key":"A","text":"It presents an experimental observation, describes how it conflicted with existing theory, and then explains how a new theoretical proposal resolved the conflict."},{"key":"B","text":"It compares two competing hypotheses about light and argues that neither fully explains the behavior of electrons."},{"key":"C","text":"It traces the career of a physicist and emphasizes the practical applications of his discoveries."},{"key":"D","text":"It describes a technological advancement and evaluates the limitations that prevented its widespread adoption."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice describing a structure of observation, conflict with theory, and resolution by a new proposal. The passage first presents Lenard''s experimental finding, then notes its contradiction with wave theory, and finally explains how Einstein''s photon hypothesis resolved the discrepancy. The choice about comparing two competing hypotheses that both fall short is wrong because the passage presents Einstein''s proposal as successfully explaining the results, not as inadequate. The choice about tracing a career and emphasizing practical applications mischaracterizes the passage, which focuses on a specific scientific problem and its resolution rather than biographical narrative or applied uses. The choice about a technological advancement and its limitations is entirely unsupported, as the passage discusses theoretical physics, not technology.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
