INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E6U9DQ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The excavation team cataloged artifacts from three distinct cultural layers at the Kalajarvi site: copper fish hooks, ceramic shards, and amber beads from the early Bronze______ birch-bark containers and bone needles from the late Neolithic period; and fragments of polished stone axes from an even earlier Mesolithic settlement.', $lyceon_json$[{"key":"A","text":"Age,"},{"key":"B","text":"Age."},{"key":"C","text":"Age:"},{"key":"D","text":"Age;"}]$lyceon_json$::jsonb, 'D', NULL, E'The sentence presents a series of three items introduced by a colon, and because the first item ("copper fish hooks, ceramic shards, and amber beads from the early Bronze Age") contains internal commas, semicolons must be used to separate the major items in the series. The later "; and" before the third item confirms this semicolon-separated structure. Using a comma after "Age" would blur the boundary between the first and second items, since commas already appear within the first item. A period would prematurely end the sentence and break the colon-introduced list. A colon serves no grammatical function at this position within an ongoing list.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
