INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H1TA57', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the Paris Conservatoire formally recognized jazz as a legitimate academic discipline in 1991, the genre ______ European concert halls for over six decades, with performers like Django Reinhardt having drawn massive audiences as early as the 1930s.', $lyceon_json$[{"key":"A","text":"fills"},{"key":"B","text":"had been filling"},{"key":"C","text":"has been filling"},{"key":"D","text":"would fill"}]$lyceon_json$::jsonb, 'B', NULL, E'The phrase "by the time...in 1991" establishes a past reference point, and the action of filling concert halls occurred over a sustained duration ("for over six decades") leading up to that point. The past perfect progressive "had been filling" correctly conveys an ongoing action that was already in progress before another past event. The present tense "fills" is inappropriate for a sentence set entirely in the past. The present perfect progressive "has been filling" implies the action continues into the present, which conflicts with the 1991 time frame. The conditional "would fill" suggests a hypothetical or habitual future-in-the-past action, which does not match the factual historical context.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
