INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L04Z17', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'In 1958, economist Albert Hirschman proposed that developing countries should pursue ''unbalanced growth'' by concentrating investment in a few strategically chosen industries rather than spreading resources evenly across all sectors. He argued that targeted investment would create supply bottlenecks and demand surpluses in adjacent industries, which would in turn provoke entrepreneurs and policymakers into making further investments to resolve those imbalances. Critics objected that this approach risked entrenching inequality between favored and neglected sectors. Hirschman acknowledged the risk but countered that ________', $lyceon_json$[{"key":"A","text":"the pressure created by deliberate imbalances would generate stronger incentives for corrective action than a balanced approach would, because balanced growth lacks the urgency that motivates investment decisions."},{"key":"B","text":"inequality between sectors was an inevitable feature of all economies, whether developed or developing, and therefore could not meaningfully be attributed to any particular investment strategy."},{"key":"C","text":"the government should directly manage all industries rather than relying on private entrepreneurs to respond to market signals."},{"key":"D","text":"developing countries should first achieve political stability before attempting any large-scale economic development strategy."}]$lyceon_json$::jsonb, 'A', NULL, E'Hirschman''s theory centers on the productive power of imbalances to provoke further investment. Acknowledging the risk of inequality while countering it logically means arguing that the imbalances themselves create useful pressure for corrective action, which balanced growth would not generate. The claim that inequality is inevitable in all economies dismisses the critics'' concern rather than countering it with Hirschman''s own mechanism of productive imbalance. The suggestion of direct government management contradicts Hirschman''s framework, which relies on entrepreneurs and policymakers responding to market pressures. The claim about political stability as a prerequisite introduces an entirely separate topic unrelated to the balanced-versus-unbalanced growth debate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M9Q4UK', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Priya Venkatesh has spent seventeen years studying the box jellyfish of northern Australia. Her latest research focuses on the creature''s venom______ which contains over forty distinct proteins capable of attacking heart cells, nerve tissue, and skin simultaneously.', $lyceon_json$[{"key":"A","text":"venom, which"},{"key":"B","text":"venom; which"},{"key":"C","text":"venom. Which"},{"key":"D","text":"venom which"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice uses a comma before "which" to set off the nonrestrictive relative clause providing additional information about the venom. The clause describes a property of the venom already identified, so it is nonrestrictive and requires a comma. Placing a semicolon before "which" would incorrectly treat the dependent clause as an independent one, and "which contains..." cannot stand alone as a sentence. Using a period before "Which" would similarly create a sentence fragment. Omitting punctuation altogether would incorrectly suggest a restrictive clause, but only one venom is under discussion, so the information is supplementary rather than identifying.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MUC25T', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'The larvae of the painted lady butterfly feed almost exclusively on thistle plants, which are abundant across temperate grasslands. _______ adult painted ladies are opportunistic nectar feeders, visiting over 100 different flowering species during their autumn migration.', E'The larvae of the painted lady butterfly feed almost exclusively on thistle plants, which are abundant across temperate grasslands. _______ adult painted ladies are opportunistic nectar feeders, visiting over 100 different flowering species during their autumn migration.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"By contrast,"},{"key":"C","text":"Consequently,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'B', NULL, E'The first sentence describes larvae that feed almost exclusively on one plant type (thistles), while the second describes adults that feed opportunistically on over 100 species. "By contrast," correctly signals the shift from a narrow, restricted diet to a broad, varied one. "Similarly," would indicate the two sentences describe comparable behaviors, but exclusive feeding on thistles is the opposite of opportunistic feeding on many species. "Consequently," implies the adult diet is caused by the larval diet, but no causal relationship is established. "Specifically," would indicate the second sentence elaborates on or narrows the first, but it introduces a different life stage with a different feeding pattern rather than refining the original claim.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N762Q9', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The entomologist Marta Kovacs -- who spent eleven years cataloging beetle species across the peat bogs of eastern Hungary and who published her findings in a monograph that was initially dismissed by her peers______ has since been vindicated by subsequent field studies confirming her count of over three hundred previously undocumented species.', $lyceon_json$[{"key":"A","text":"peers --"},{"key":"B","text":"peers,"},{"key":"C","text":"peers;"},{"key":"D","text":"peers"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence uses a pair of dashes to set off a long nonrestrictive parenthetical element beginning after "Kovacs" and describing her research. A closing dash after "peers" is required to complete this pair and return to the main clause ("has since been vindicated"). Using a comma would create a mismatch with the opening dash, producing inconsistent punctuation around the parenthetical. A semicolon would incorrectly attempt to join clauses, but "has since been vindicated" lacks a subject and cannot function as an independent clause after a semicolon. Omitting punctuation entirely would fail to close the parenthetical element, leaving the sentence structure unresolved and the main verb stranded.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NMMDHI', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The community garden on Elm Terrace, maintained by a rotating group of seventeen volunteers from the surrounding neighborhood, ______ fresh produce to local families every Saturday morning from June through October.', $lyceon_json$[{"key":"A","text":"provide"},{"key":"B","text":"are providing"},{"key":"C","text":"provides"},{"key":"D","text":"providing"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the sentence is "The community garden," which is singular. The prepositional phrase "on Elm Terrace" and the participial phrase "maintained by a rotating group of seventeen volunteers" are modifiers that do not change the number of the subject. The singular verb "provides" correctly agrees with the singular subject "garden." The plural forms "provide" and "are providing" incorrectly treat the subject as plural, likely confusing the nearby noun "volunteers" for the subject. Using "providing" without a helping verb creates a participial phrase rather than a finite verb, leaving the sentence without a main predicate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PLC22P', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which quotation from a research article would, if accurate, most effectively support the literary scholar''s interpretation presented in the text?', E'Literary scholar Tomoko Arai contends that the Brazilian novelist Clarice Lispector used recurring water imagery in her 1964 novel The Passion According to G.H. not as a conventional symbol of purification or rebirth, but as a representation of the protagonist''s dissolving sense of individual identity. Arai argues that each instance of water imagery in the novel corresponds to a moment when the protagonist''s psychological boundaries between self and world become less distinct, ultimately culminating in a state Arai terms ''ontological porosity.''', $lyceon_json$[{"key":"A","text":"\"In our analysis of forty-seven water-image passages in The Passion According to G.H., we found that thirty-nine occur within scenes where the narrator explicitly questions the boundaries of her own subjectivity, and none occur in passages associated with moral transformation or spiritual cleansing.\""},{"key":"B","text":"\"Lispector's use of water imagery is consistent with the broader tradition of Brazilian modernist fiction, in which natural elements frequently symbolize national identity and cultural renewal.\""},{"key":"C","text":"\"Our corpus analysis reveals that water imagery appears with greater frequency in Lispector's later novels than in her early works, suggesting a gradual evolution in her symbolic vocabulary.\""},{"key":"D","text":"\"Scholars have long debated whether Lispector's imagery is best understood through psychoanalytic, existentialist, or phenomenological frameworks, and no consensus has emerged.\""}]$lyceon_json$::jsonb, 'A', NULL, E'Arai''s interpretation holds that water imagery represents dissolving identity boundaries, not purification or rebirth. The quotation finding that thirty-nine of forty-seven water passages coincide with the narrator questioning her subjectivity, and none with moral or spiritual cleansing, directly supports both the positive claim (identity dissolution) and the negative claim (not purification). The quotation about Brazilian modernist tradition links water to national identity and cultural renewal, which aligns with the conventional symbolism Arai rejects. The frequency analysis across Lispector''s career addresses the evolution of her imagery over time but says nothing about what the imagery represents in this particular novel. The observation about scholarly disagreement among frameworks describes the state of debate without providing evidence for any specific interpretation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PWM5LQ', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists Yuki Tanabe and Priya Deshmukh have hypothesized that the giant Pacific octopus navigates its rocky intertidal habitat primarily through chemoreception rather than vision. They note that the species''s suckers contain dense clusters of chemosensory receptors and that octopuses in murky, low-visibility waters appear to locate prey with the same efficiency as those in clear waters.', $lyceon_json$[{"key":"A","text":"Giant Pacific octopuses with experimentally impaired vision locate prey at rates comparable to those of unimpaired octopuses in identical environments."},{"key":"B","text":"The giant Pacific octopus has significantly larger eyes relative to body size than most other octopus species."},{"key":"C","text":"Giant Pacific octopuses in captivity show a strong preference for brightly colored prey items over dull-colored ones."},{"key":"D","text":"The chemosensory receptors in octopus suckers are structurally similar to taste receptors in vertebrate tongues."}]$lyceon_json$::jsonb, 'A', NULL, E'If octopuses with impaired vision still locate prey effectively, that directly supports the hypothesis that chemoreception, not vision, is the primary navigation sense. The finding about large eye size would suggest vision is important, which undermines rather than supports the hypothesis. A preference for brightly colored prey would suggest reliance on vision, contradicting the chemoreception hypothesis. The structural similarity of chemosensory receptors to vertebrate taste receptors describes receptor anatomy but does not demonstrate that chemoreception is the primary navigational sense.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R2XTDQ', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly weaken the claim made in the text?', E'Agricultural economist Deirdre Nwosu argues that sub-Saharan African farmers who adopt drought-resistant millet varieties experience yield gains primarily because these varieties allow planting to begin seventeen days earlier in the season, not because the varieties themselves produce more grain per plant under identical conditions. According to Nwosu, the earlier planting window is the mechanism through which drought-resistant millet improves total harvest output.', $lyceon_json$[{"key":"A","text":"In controlled greenhouse trials where planting date is held constant, drought-resistant millet varieties produce twenty-three percent more grain per plant than traditional varieties under moderate water stress."},{"key":"B","text":"Farmers who plant drought-resistant millet also tend to use more fertilizer than farmers who plant traditional varieties."},{"key":"C","text":"Drought-resistant millet varieties were first developed in the 1980s by agricultural researchers in Senegal."},{"key":"D","text":"Some sub-Saharan African countries have experienced increasing rainfall variability over the past two decades."}]$lyceon_json$::jsonb, 'A', NULL, E'Nwosu claims yield gains come from earlier planting, not from the varieties'' inherent grain production. If controlled trials with identical planting dates show drought-resistant millet producing significantly more grain per plant, that directly contradicts her claim by demonstrating an inherent yield advantage independent of planting timing. The finding about fertilizer use introduces a confounding variable but does not directly address whether the varieties themselves produce more grain. The historical origin of the varieties is irrelevant to the mechanism behind yield gains. Increasing rainfall variability provides general climate context but does not speak to the specific mechanism Nwosu identifies.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SGV6VJ', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SJAN85', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 2019, the city council of Tallinn, Estonia, approved an unconventional proposal for reducing air pollution in the downtown corridor______ the installation of seventy-three vertical garden panels along the facades of government buildings. The panels, designed by architect Kairi Mets, filter particulate matter while absorbing carbon dioxide.', $lyceon_json$[{"key":"A","text":"corridor;"},{"key":"B","text":"corridor,"},{"key":"C","text":"corridor:"},{"key":"D","text":"corridor"}]$lyceon_json$::jsonb, 'C', NULL, E'A colon is the correct punctuation because the first part of the sentence is an independent clause that introduces a specific proposal, and what follows ("the installation of seventy-three vertical garden panels...") identifies what that proposal is. A colon properly signals this explanatory relationship. A semicolon would be incorrect because the noun phrase that follows is not an independent clause. A comma produces a weak and ambiguous join between the main clause and the appositive that names the proposal. Omitting punctuation entirely creates a run-on that merges the main clause with the appositive without any grammatical signal.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2T3DCKJ', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Historian Marisol Fuentes argues that the traditional narrative of the 1847 Caste War in the Yucatan Peninsula is ______, omitting the perspectives of Maya women who organized supply networks that sustained resistance fighters for nearly a decade.', $lyceon_json$[{"key":"A","text":"meticulous"},{"key":"B","text":"incomplete"},{"key":"C","text":"inflammatory"},{"key":"D","text":"hypothetical"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is "incomplete." The passage states that the traditional narrative omits the perspectives of Maya women, meaning the account is missing important elements -- which is precisely what "incomplete" conveys. "Meticulous" means extremely careful and thorough, which contradicts the claim that perspectives are being omitted. "Inflammatory" means tending to provoke anger or outrage, which describes an emotional quality rather than the structural gap in the narrative the passage identifies. "Hypothetical" means based on conjecture rather than evidence, but the passage does not question whether the narrative''s claims are speculative -- it criticizes what the narrative leaves out.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VQEZYU', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The grant committee deliberated for three weeks before selecting the two researchers ______ the panel considered most likely to produce replicable results: Dr. Okafor, whose work on synaptic plasticity had already garnered international recognition, and Dr. Lindqvist, whose novel imaging technique promised to reshape the field.', $lyceon_json$[{"key":"A","text":"whom"},{"key":"B","text":"who"},{"key":"C","text":"which"},{"key":"D","text":"whose"}]$lyceon_json$::jsonb, 'A', NULL, E'The pronoun serves as the object of "considered" in the relative clause "the panel considered [the researchers] most likely to produce replicable results." Because the pronoun functions as an object rather than a subject, the objective case "whom" is required. The nominative "who" would be correct only if the pronoun were the subject of a verb, but here "the panel" is the subject of "considered." The pronoun "which" is reserved for things, not people. The possessive "whose" does not fit the syntactic structure, as no possession is being expressed at this point in the sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VQWHD6', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Geochemist Clair Patterson spent years developing ultra-clean laboratory techniques to eliminate lead contamination from his samples. _______ he was able to determine the age of the Earth at 4.55 billion years, a figure that remains accepted today.', E'Geochemist Clair Patterson spent years developing ultra-clean laboratory techniques to eliminate lead contamination from his samples. _______ he was able to determine the age of the Earth at 4.55 billion years, a figure that remains accepted today.', $lyceon_json$[{"key":"A","text":"As a result,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence describes an outcome (determining the Earth''s age) that directly followed from the action in the first sentence (developing clean lab techniques). "As a result," correctly signals this cause-and-effect relationship. "Nevertheless," implies a concession or contrast with an expectation, but there is no opposing idea to concede. "In contrast," signals a comparison between differing elements, which does not fit because the two sentences are causally linked, not opposed. "For instance," introduces an example of a broader claim, but the second sentence is a consequence, not an illustration.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X66DR2', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'In the early 1900s, entomologist William Morton Wheeler observed that certain ant colonies would ______ their foraging routes in response to seasonal flooding, abandoning familiar trails to establish entirely new paths across higher ground.', $lyceon_json$[{"key":"A","text":"redirect"},{"key":"B","text":"commemorate"},{"key":"C","text":"fabricate"},{"key":"D","text":"deplete"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "redirect." The passage describes ants changing their foraging routes by abandoning old trails and establishing new ones on higher ground, which is precisely what "redirect" means -- to change the course or direction of something. "Commemorate" means to honor or remember something, which has no connection to changing paths. "Fabricate" means to construct or invent something, particularly something false, which does not fit the context of changing existing routes. "Deplete" means to use up or exhaust a resource, which is unrelated to altering pathways.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XBEK4R', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Turku have found that the Eurasian jay, a corvid native to forests across Europe and Asia, can recall the specific location and contents of over seventy cached food items after a delay of thirty-three days. In controlled experiments, the jays consistently retrieved perishable items before non-perishable ones, suggesting that they not only remember where they hid food but also track how long ago each item was stored. These results place the Eurasian jay alongside the scrub-jay as a species demonstrating episodic-like memory previously thought unique to primates.', $lyceon_json$[{"key":"A","text":"Eurasian jays can remember the locations and freshness of dozens of cached food items over extended periods, demonstrating episodic-like memory."},{"key":"B","text":"The Eurasian jay is more intelligent than other corvid species because it can store food in over seventy locations."},{"key":"C","text":"Scientists have proven that episodic memory is not unique to primates by studying a wide range of bird species."},{"key":"D","text":"The scrub-jay was the first corvid shown to have episodic-like memory, and the Eurasian jay has since replaced it as the primary research subject."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes research showing that Eurasian jays remember where they cached food and how long ago, retrieving perishable items first, which constitutes episodic-like memory. The answer stating that Eurasian jays remember locations and freshness over extended periods captures this central finding. The claim that Eurasian jays are more intelligent than other corvids overstates the passage, which compares the jays only to primates regarding episodic-like memory. The claim about a wide range of bird species distorts the passage, which discusses only two corvid species. The suggestion that the Eurasian jay replaced the scrub-jay as the primary research subject is unsupported; the passage simply notes the scrub-jay as another species with this ability.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XBV9DP', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best states the main idea of the text?', E'In the 1990s, computational linguist Karen Sparck Jones argued that natural language processing systems should be evaluated not by how well they mimicked human grammar but by how effectively they completed real-world tasks such as document retrieval and text summarization. Her stance was controversial at the time because most NLP researchers favored formal linguistic models that prioritized syntactic correctness. However, the subsequent rise of statistical and neural approaches to language processing vindicated Sparck Jones''s pragmatic orientation: today, NLP systems are overwhelmingly judged by task-specific performance benchmarks rather than by adherence to grammatical theory.', $lyceon_json$[{"key":"A","text":"Karen Sparck Jones's argument that NLP systems should be evaluated by real-world task performance was initially controversial but was ultimately validated by the field's shift toward statistical and neural methods."},{"key":"B","text":"Formal linguistic models were abandoned in the 1990s because they could not handle the complexity of natural language grammar."},{"key":"C","text":"Neural approaches to language processing are more accurate than statistical approaches, which Sparck Jones originally championed."},{"key":"D","text":"The field of computational linguistics has always prioritized practical applications over theoretical models of syntax."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage traces a narrative arc: Sparck Jones advocated task-based evaluation, her position was controversial among grammar-focused researchers, and later developments in statistical and neural NLP proved her right. The correct choice captures this full arc. The claim that formal linguistic models were abandoned in the 1990s contradicts the passage, which says most researchers in the 1990s still favored them. The suggestion that neural approaches are more accurate than statistical ones, or that Sparck Jones championed only statistical methods, introduces distinctions the passage does not make. The claim that the field has always prioritized practical applications directly contradicts the passage''s statement that formal models dominated at the time of Sparck Jones''s argument.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
